def find_path(graph, start, goal):
    # Initialize data structures
    visited = set()  # Nodes already visited
    path = {start: [start]}  # Stores path from start to each node

    # Depth-First Search (DFS)
    def dfs(node, goal):
        if node in visited:
            return None
        visited.add(node)
        if node == goal:
            return path[node]
        for neighbor in graph.get(node, []):
            result = dfs(neighbor, goal)
            if result:
                path[node] = [node] + result
                return path[node]
        return None

    return dfs(start, goal)
