def find_path(graph, start, goal):
    if start == goal:
        return [start]

    # Keep track of all visited nodes to avoid cycles
    visited = set()
    # Dictionary to keep track of the path from start to current node
    path = {start: [start]}

    while path:
        current = None
        # Find the node with the shortest known distance
        for node in path:
            if current is None or len(path[node]) <= len(path[current]):
                current = node

        # If we have reached the goal, return the path
        if current == goal:
            return path[current]

        # Explore neighbors
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                new_path = path[current][:]
                new_path.append(neighbor)
                path[neighbor] = new_path
                visited.add(neighbor)

        # Remove the current node from the path dictionary
        del path[current]

    # If the goal was not reached, return None
    return None
